internal abstract class UPSPricingAttributePriceGroup extends UPSAbstractPricingAttribute implements UPSIPricingAttribute
{
}

Method.Source:
public static Map getAttributesInRule(UPSPricingRule _rule)
{
    var attributesValueMap = new Map(Types::AnyType, Types::String);

    UPSPricingAttributeLink attrLink;
    UPSPricingAttributeLink attrLink1;
    UPSPricingRuleCondition ruleCond;
    UPSPricingAttributeGroup attributeGroup;

    while select ruleCond
        join attrLink
        where attrLink.RecId == ruleCond.ConditionAttribute
            && ruleCond.RuleId == _rule.RecId
        outer join attributeGroup
            where attributeGroup.Name == ruleCond.ConditionValue
                && (attrLink.Source == UPSPricingAttributeSource::CustomerPriceGroup
                    ||  attrLink.Source == UPSPricingAttributeSource::ProductPriceGroup)
        outer join attrLink1
            where attrLink1.PriceAttributeGroup == attributeGroup.RecId
    {
        if(!attrLink1)
        {
            attributesValueMap.insert(attrLink, ruleCond.ConditionValue);
        }
        else
        {
            attributesValueMap.insert(attrLink1, attrLink1.DefaultValue);
        }
    }
    return attributesValueMap;
}

public QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(UPSPricingAttributeGroup)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(UPSPricingAttributeGroup));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(UPSPricingAttributeGroup));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(UPSPricingAttributeGroup), qbdsRoot);
        }
    }

    return qbdsRoot;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qbdsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
